def experiment(inputs):
    import random
    trials = inputs.get('trials', [])
    results = []
    for trial in trials:
        vals = list(trial.get('values', []))
        vals.sort()
        results.append({
            'id': trial.get('id'),
            'sorted_values': vals
        })
    return {'trials': results}

def experiment(inputs):
    trials = inputs.get('trials', [])
    results = []
    def multi_tier_sort(vals):
        if len(vals) <= 1:
            return vals
        mid = len(vals) // 2
        left = multi_tier_sort(vals[:mid])
        right = multi_tier_sort(vals[mid:])
        return sorted(left + right)
    for trial in trials:
        vals = list(trial.get('values', []))
        results.append(multi_tier_sort(vals))
    return results

